async function cdqOpenPdf(id){
  afficherMessage('Préparation du PDF…',true);
  try{
    const rec=await cdqLoadPdfRecord(id);
    if(cdqPdfReaderPreference()==='cdq')await cdqOpenPdfInternal(id,rec);
    else cdqShowPdfReaderChoice(id,rec);
    return true;
  }
  catch(e){afficherErreur(e);throw e;}
}
window.cdqOpenPdf=cdqOpenPdf;

// Tap normal : les PDF utilisent directement le lecteur CDQ/PDF.
